const e="trinidad-junior-soca-competition",u=2024,i="Read in full: all 4 pages (cover, definitions and interpretation, management, the competition, registration, compositions, judging, performance procedures, discipline, recordings, prizes). This is the 2024 edition, so dates, venues and prize amounts are Variables (the starting suggestion for the next edition). The finals venue is printed as 'to be determined' and is kept as a Variable with those words. The rules print no entry fee, no contact person or phone number, no school or age proof requirement, and no points other than the 100-point judging scale; so these are left empty. The prizes are money amounts only, no placing points. Rule 7.4 says positions are decided by a number system; it is written as drawing numbers.",t={Title:"Rules & Criteria",Subtitle:"Ministry of Education Junior Soca Competition. Preliminaries on {{PreliminariesDate}}, finals on {{FinalsDate}}.",NoticeTitle:"Please Read Before Registering",Notice:"Register online by {{RegistrationDeadline}}. Preliminaries are on {{PreliminariesDate}} at {{PreliminariesTime}} at {{PreliminariesVenue}}. Finals are on {{FinalsDate}} at {{FinalsTime}}; the finals venue is {{FinalsVenue}}. Only registered artistes and schools may take part.",Notes:["Where these rules are silent, the decision of the Ministry's representatives is final and binding on all parties."],Sections:[{Key:"general",Title:"General Rules",Items:["The Junior Soca Competition is created by the Ministry of Education for students to show their talent in the Soca genre.","The competition is managed by the Visual and Performing Arts (VAPA) Unit of the Curriculum Planning and Development Division, Ministry of Education.","The Ministry may co-opt personnel to carry out any duty named in the rules.","The rules are read under the laws of the Republic of Trinidad and Tobago.","On any matter where the rules are silent, the decision of the Ministry's representatives is final and binding on all parties.","The competition has two stages, preliminaries and finals. A panel of adjudicators judges both with set judging criteria.","The Ministry of Education and the Ministry of Communications, or their agents, may record the performances of artistes and supporters on audio, video or other media and use the recordings as they decide.","Registering under these rules, with the signature of a person authorised to act for the artiste and school, is accepted as consent to the recording.","Definitions printed: Artiste means a student or performer in the age limit who performs or plans to perform; an Official is a person the Ministry names to manage the competition; the Registration Form is the form the Ministry provides for registration."]},{Key:"eligibility",Title:"Who Can Enter",Items:["The competition is open to bonafide students of primary and secondary institutions, both public and private.","Students must be no older than 19 years.","The two categories are Primary/Junior and Secondary/Senior.","Only registered artistes and schools may take part.","There is no limit to the number of students from one school who may enter.","A piece that was judged in any earlier competition may not be entered."]},{Key:"registration",Title:"How to Register",Items:["Each artiste must register online with the Ministry of Education at {{RegistrationLink}}.","The last date to register is {{RegistrationDeadline}}.","The Ministry provides a Registration Form for the information needed to register.","Contestants report to the Stage Manager at least 1 hour before their performance time.","Contestants give the technical officials their musical track when they arrive at the venue."]},{Key:"dates",Title:"Dates and Times",Items:["Preliminaries: {{PreliminariesDate}}, start time {{PreliminariesTime}}.","Finals: {{FinalsDate}}, start time {{FinalsTime}}."]},{Key:"venue",Title:"Venue",Items:["Preliminaries venue: {{PreliminariesVenue}}.","Finals venue: {{FinalsVenue}}."]},{Key:"judging",Title:"Judging",Items:["Each adjudicator marks an artiste out of a maximum of 100 points.","Melody (suitability, appropriateness, phrasing): 25 points.","Lyrics (creativity, descriptiveness, metering, rhyme scheme, clarity of message, development of the theme): 25 points.","Rendition (intonation, clarity of diction, enunciation, articulation): 20 points.","Arrangement (Soca genre, musical accompaniment, vocal arrangement): 10 points.","Performance (communication, visual impact, body language, use of stage, use of props): 20 points.","The decision of the judges is final and binding. Artistes, parents and supporters must accept the results and behave in an exemplary way.","Performance positions are decided by drawing numbers."]},{Key:"conduct",Title:"Conduct and Discipline",Items:["Songs must be of the Soca genre.","Lyrics must not be libellous or defamatory and must not incite violence. An artiste who performs such a song is disqualified.","An artiste is disqualified if the rendition is judged inappropriate in characterisation, lyrics, attire, body language or displayed signs.","No fire products or other incendiary props are allowed.","Contestants and supporters must not incite violence, damage property or use obscene language. These acts can lead to disqualification or arrest by security officials.","A contestant who does not report to the Stage Manager at least 1 hour before the performance is late and loses 10 points.","If an artiste or school does not follow the rules without a good reason that satisfies the Ministry, the Ministry may censure, fine, deduct points or disqualify. The Ministry's decision is final and binding.","A disqualified artiste or school receives no prize money."]},{Key:"prizes",Title:"Prizes",Items:["Secondary (Seniors) prize money: {{SeniorPrizes}}","Primary (Juniors) prize money: {{JuniorPrizes}}"]}],Documents:[{Title:"Junior Soca Competition 2024 Rules & Regulations",Url:"https://storage.moe.gov.tt/wpdevelopment/2024/01/JUNIOR-SOCA-COMPETITION-Rules-Regulations-2024.pdf"}]},n=[],o=[{AgeGroup:"Primary Junior",Source:"Junior Soca Competition 2024 Rules & Regulations p.2 and p.4",Sections:{About:null,TimeAndFormat:null,Rules:["Primary/Junior category. Prize money is printed separately for this category."],Allowed:null,NotAllowed:null,Judging:null,Points:["Prize money: {{JuniorPrizes}}"],Notes:null},Markdown:`## Rules
- Primary/Junior category. Prize money is printed separately for this category.

## Points
- Prize money: {{JuniorPrizes}}`},{AgeGroup:"Secondary Sr",Source:"Junior Soca Competition 2024 Rules & Regulations p.2 and p.4",Sections:{About:null,TimeAndFormat:null,Rules:["Secondary/Senior category. Prize money is printed separately for this category."],Allowed:null,NotAllowed:null,Judging:null,Points:["Prize money: {{SeniorPrizes}}"],Notes:null},Markdown:`## Rules
- Secondary/Senior category. Prize money is printed separately for this category.

## Points
- Prize money: {{SeniorPrizes}}`}],a=[{Title:"Soca Song",Source:"Junior Soca Competition 2024 Rules & Regulations p.2-3 (sections 5 and 7)",Sections:{About:["The artiste performs one Soca song. The entry is the individual artiste."],TimeAndFormat:["The song is performed in 3 to 5 minutes.","The most time allowed on stage is 7 minutes, including setting up and striking props, the presentation and the rendition.","The artiste brings a CD or flash drive with an instrumental accompaniment in Mp3, Mp4 or Wav format.","The track must have no lead voice singing the melody. Backup vocals only are allowed on the track."],Rules:["A maximum of 3 back-up singers is allowed.","A maximum of 7 supporting persons, including dancers and actors, is allowed on stage during a performance.","Back-up singers and dancers must not be over 19 years of age.","No adult support or accompaniment is allowed on stage without prior permission."],Allowed:null,NotAllowed:null,Judging:["Melody 25, Lyrics 25, Rendition 20, Arrangement 10, Performance 20: 100 points in all per adjudicator."],Points:null,Notes:null},Markdown:`## About this competition
- The artiste performs one Soca song. The entry is the individual artiste.

## Time and format
- The song is performed in 3 to 5 minutes.
- The most time allowed on stage is 7 minutes, including setting up and striking props, the presentation and the rendition.
- The artiste brings a CD or flash drive with an instrumental accompaniment in Mp3, Mp4 or Wav format.
- The track must have no lead voice singing the melody. Backup vocals only are allowed on the track.

## Rules
- A maximum of 3 back-up singers is allowed.
- A maximum of 7 supporting persons, including dancers and actors, is allowed on stage during a performance.
- Back-up singers and dancers must not be over 19 years of age.
- No adult support or accompaniment is allowed on stage without prior permission.

## Judging
- Melody 25, Lyrics 25, Rendition 20, Arrangement 10, Performance 20: 100 points in all per adjudicator.`}],r=[],s=[{Key:"RegistrationDeadline",Kind:"date",Label:"Last date to register",Value:"2024-01-16",Source:"Junior Soca Competition 2024 Rules & Regulations p.2 (4B Registration Deadline Date)"},{Key:"PreliminariesDate",Kind:"date",Label:"Preliminaries date",Value:"2024-01-25",Source:"Junior Soca Competition 2024 Rules & Regulations p.2 (3.4)"},{Key:"PreliminariesTime",Kind:"time",Label:"Preliminaries start time",Value:"9:30 a.m.",Source:"Junior Soca Competition 2024 Rules & Regulations p.2 (3.4)"},{Key:"PreliminariesVenue",Kind:"address",Label:"Preliminaries venue",Value:{Name:"Auditorium, RCLRC",Address:"Mc Bean",City:"Couva",MapUrl:"",Directions:""},Source:"Junior Soca Competition 2024 Rules & Regulations p.2 (3.5)"},{Key:"FinalsDate",Kind:"date",Label:"Finals date",Value:"2024-02-08",Source:"Junior Soca Competition 2024 Rules & Regulations p.2 (3.6)"},{Key:"FinalsTime",Kind:"time",Label:"Finals start time",Value:"10 a.m.",Source:"Junior Soca Competition 2024 Rules & Regulations p.2 (3.6)"},{Key:"FinalsVenue",Kind:"address",Label:"Finals venue",Value:{Name:"To be determined",Address:"",City:"",MapUrl:"",Directions:""},Source:"Junior Soca Competition 2024 Rules & Regulations p.2 (3.7 The venue for the finals is to be determined)"},{Key:"RegistrationLink",Kind:"link",Label:"Online registration page",Value:"https://www.moe.gov.tt/national-schools-carnival-events-2024/",Source:"Junior Soca Competition 2024 Rules & Regulations p.2 (4.1)"},{Key:"SeniorPrizes",Kind:"prize",Label:"Prize money: Secondary (Seniors)",Value:"1st $9,000; 2nd $6,000; 3rd $4,000; 4th $2,500; 5th to 10th $1,500 each. Sub-total $30,000.",Source:"Junior Soca Competition 2024 Rules & Regulations p.4 (10.1)"},{Key:"JuniorPrizes",Kind:"prize",Label:"Prize money: Primary (Juniors)",Value:"1st $6,000; 2nd $4,000; 3rd $3,000; 4th $1,500; 5th to 10th $1,000 each. Sub-total $20,500.",Source:"Junior Soca Competition 2024 Rules & Regulations p.4 (10.1)"}],l=[{Claim:"Every rule, date, venue, prize and criterion on this page is from the Junior Soca Competition 2024 Rules & Regulations (pages 1 to 4).",SourceType:"Primary - the event's own rules document",Source:"Junior Soca Competition 2024 Rules & Regulations",Url:"https://storage.moe.gov.tt/wpdevelopment/2024/01/JUNIOR-SOCA-COMPETITION-Rules-Regulations-2024.pdf"}],d={TemplateKey:e,Year:2024,Note:i,Page:t,ParticipantTypes:n,AgeGroups:o,Competitions:a,CompetitionAgeGroups:r,Variables:s,Evidence:l};export{o as AgeGroups,r as CompetitionAgeGroups,a as Competitions,l as Evidence,i as Note,t as Page,n as ParticipantTypes,e as TemplateKey,s as Variables,u as Year,d as default};
